# -*- coding: utf-8 -*-
# Drass Wealth Management -- the fourth platform, previously undocumented.
DRASS = [
 dict(id="DR-01", name="Licensed Delivery Shell",
  metaphor="a concert hall that hosts the orchestra without owning a single instrument",
  simple="Imagine a concert hall that puts on a world-class show every night but does not own one violin. The musicians arrive, play, and leave with their instruments. Drass works the same way: the website shows the calculators, but the thinking happens somewhere else entirely. Nothing about how the math works ever lives on the Drass server. The firm gets the whole show without ever holding the sheet music.",
  works="The Drass website holds only the seats and the stage lighting: the page layout, the headings, the place where an answer appears. Every actual calculation is asked for over a protected connection, run on the owner's platform, and sent back as a finished answer. If the connection is not set up, the page says so plainly instead of pretending to work. The licensed site can be taken away at any time without the engines going with it.",
  patentable="Nobody has built a licensing arrangement where the rendering site is deliberately incapable of performing the invention it displays. The emergent capability is that a firm can offer patented tools to its clients while the patent holder keeps every piece of the protected mechanism, and can withdraw it instantly. This separation of display from computation, enforced in the software rather than in a contract, is new.",
  alice=7, alice_why="A concrete client-server architecture with an enforced capability boundary reads as technical, not as an abstract business arrangement.",
  priority="High importance",
  urgency="This is the pattern every future licensee will use, so it is the one that gets copied first. A competitor who sees the Drass site can infer the arrangement in an afternoon and build their own version before you file. It also underpins the revenue model for every firm after Drass, which makes it load-bearing rather than optional. File it before the second licensee goes live, because the second deployment is the public proof that the pattern works."),
 dict(id="DR-02", name="Refuse-Before-Render Compliance Gate",
  metaphor="a pharmacist who will not hand over the bottle until the label is right",
  simple="Imagine a pharmacist who physically cannot pass you a bottle until every warning is printed on the label. Not a reminder, not a sticky note, a hard stop. That is what this does for financial calculators. A tool that has not satisfied its compliance rules will not draw a single number on the screen. The refusal is part of the machine, not a policy someone can forget.",
  works="Before any figure reaches the page, the tool asks a separate checker whether this particular calculation is allowed to be shown, in this mode, with these assumptions. The checker answers yes or no, and a no produces a plain explanation instead of a result. Historical illustrations carry their own stricter test, because showing what would have happened is the easiest way to mislead someone. Nothing renders around the refusal, so there is no half-answer to misread.",
  patentable="Compliance software normally reviews output after it exists, or warns a human. Here the compliance decision happens upstream of generation, so a non-compliant figure is never produced at all. The emergent capability is a calculator that cannot be made to say the wrong thing, even by its own operator.",
  alice=8, alice_why="A generation-blocking control in the execution path is a specific technical mechanism, not a rule someone follows.",
  priority="Critical to file",
  urgency="Regulated software is heading toward exactly this design, and whoever files first owns the shape of it. The mechanism is visible in the product's behaviour, so any examiner or competitor can observe it working. It also protects the most dangerous surface you have, which is a number shown to a client who then acts on it. Delay here risks both the patent and a compliance incident that a filed claim would have forced you to design around anyway."),
 dict(id="DR-03", name="One Identity, Two Faces",
  metaphor="a hotel key card that opens the staff corridor or the guest room depending on who is holding it",
  simple="Imagine one key card that opens completely different doors depending on whose hand it is in. Staff get the service corridors; guests get their room and the pool. Same card, same lock, different world behind it. This invention gives one sign-in that opens an advisor's view or a client's view without either person knowing the other view exists. The person never picks a role; the card already knows.",
  works="A person signs in once at the platform that owns the accounts. That platform hands back a sealed note saying who they are and what they are, and the licensed website checks the seal before believing a word of it. The note decides which interface is built, and the site never assembles the other one. Because the sealed note also carries its own expiry, the borrowed session can never outlive the real one.",
  patentable="Role-based access normally happens inside one application after login. Here the role travels across a company boundary inside a verified token and determines which interface is constructed at all. The emergent capability is that a licensed third-party site can serve two audiences with different rights while holding no account records of its own.",
  alice=7, alice_why="Cross-domain token verification driving interface construction is concrete, though the surrounding idea of roles is old and must be claimed narrowly.",
  priority="High importance",
  urgency="This shipped as working code before this document was written, which starts a clock you cannot pause. Public use begins the moment the first advisor signs in on the live Drass site. The mechanism is also the doorway for every later feature, so a gap here weakens everything built on top. File within the grace window rather than counting on it."),
 dict(id="DR-04", name="Patent 360 Advisor Console",
  metaphor="an X-ray that shows the skeleton under a finished portrait",
  simple="Imagine looking at a finished portrait and being able to switch on an X-ray that shows every bone underneath. The face stays the same, but now you can see the structure holding it up. Patent 360 does that for a client's plan: the advisor sees which protected engines touched it, in what order, and what each one contributed. The client sees the portrait. The advisor sees the skeleton.",
  works="Every time a protected engine runs for a client, the system quietly notes which engine it was, when it ran, and what it changed. The advisor's console reads that trail and lays it out as a map of the plan's construction. Because the trail is written as the work happens rather than reconstructed afterward, it cannot drift from what actually occurred. Clients never see this view and are never told a different story because of it.",
  patentable="No planning platform exposes its own intellectual property as a navigable layer for the professional using it. The emergent capability is that an advisor can explain exactly which invention produced which part of a recommendation, turning a patent portfolio into a sales instrument and an audit record at once.",
  alice=6, alice_why="Risks reading as record-keeping unless the claim is tied to the write-as-you-go provenance trail rather than the display.",
  priority="Important",
  urgency="The value here is commercial rather than defensive, so the filing can follow the stronger ones. It does become urgent the moment advisors start demonstrating it in client meetings, because that is public use. It is also the most copyable idea in the set, since the concept is obvious once seen. Keep it in the same filing family so it inherits the earlier priority date."),
]
